"""Runtime support for vecDSL programs generated for DuckDB with the vss and fts extensions. Generated by vecDSL 7. Do not edit.

DuckDB runs inside this process over one database file; there is no server. Every statement arrives as SQL text with
numbered parameters ($1, $2, ...), identical in the Python, TypeScript and Java programs. Parameters are sent as text
(lists and objects as JSON text) and cast in the SQL; queries return one JSON value per row. Each call runs in its own
transaction (BEGIN ... COMMIT). Search settings are applied with SET before the statement and RESET after it, because
DuckDB has no SET LOCAL.
"""

from __future__ import annotations

import json
import math
import os
import re
from importlib.metadata import PackageNotFoundError, version
from typing import Any, NoReturn, Sequence

SDK_PACKAGE = "duckdb"
SDK_MIN = "{{sdk.python.min}}"
SDK_MAX = "{{sdk.python.max}}"
EXTENSIONS = ("vss", "fts")

_DIGITS = 6
_BATCH = 500
_SETTING = re.compile(r"[a-z_]+")
_SETTING_VALUE = re.compile(r"[0-9]+|true|false")


class UnsupportedFeature(NotImplementedError):
    pass


def _version_tuple(text: str) -> tuple[int, ...]:
    parts = []
    for token in re.split(r"[.+\-]", text.lstrip("v")):
        if not token.isdigit():
            break
        parts.append(int(token))
    return tuple(parts)


def requirement() -> str:
    return f"{SDK_PACKAGE}>={SDK_MIN},<{SDK_MAX}"


def check_sdk() -> str:
    try:
        installed = version(SDK_PACKAGE)
    except PackageNotFoundError as error:
        raise ImportError(f"{SDK_PACKAGE} is not installed; install '{requirement()}'") from error
    if not _version_tuple(SDK_MIN) <= _version_tuple(installed) < _version_tuple(SDK_MAX):
        raise ImportError(f"{SDK_PACKAGE} {installed} is not supported; install '{requirement()}'")
    return installed


check_sdk()

import duckdb  # noqa: E402


def unsupported(vendor: str, feature: str) -> NoReturn:
    raise UnsupportedFeature(f"{feature} is not supported for target {vendor}")


def env(name: str) -> str:
    value = os.environ.get(name)
    if value is None:
        raise KeyError(f"environment variable {name} is not set")
    return value


def _packaged_extensions() -> str | None:
    """The extension directory of the duckdb-core-ext-vss package, when it is installed (DuckDB's Python extension wheels)."""
    try:
        import duckdb_core_ext_vss
    except ImportError:
        return None
    return str(duckdb_core_ext_vss.get_extensions_dir())


def _literal(text: str) -> str:
    return "'" + text.replace("'", "''") + "'"


class Client:
    """One in-process DuckDB connection: the extensions are loaded first, then the database file is attached and used."""

    def __init__(self, path: str, read_only: bool = False, extension_directory: str | None = None) -> None:
        self.path = path
        self.read_only = read_only
        self.connection = duckdb.connect(":memory:")
        directory = extension_directory or _packaged_extensions()
        if directory:
            self.connection.execute("SET extension_directory = " + _literal(directory))
        for name in EXTENSIONS:
            self._load(name)
        self.connection.execute("SET hnsw_enable_experimental_persistence = true")
        self.connection.execute("SET hnsw_prefilter = true")
        if path != ":memory:":
            parent = os.path.dirname(os.path.abspath(path))
            os.makedirs(parent, exist_ok=True)
            mode = " (READ_ONLY)" if read_only else ""
            self.connection.execute(f"ATTACH {_literal(path)} AS vecdsl{mode}")
            self.connection.execute("USE vecdsl")

    def _load(self, name: str) -> None:
        try:
            self.connection.execute(f"LOAD {name}")
            return
        except duckdb.Error:
            pass
        try:
            self.connection.execute(f"INSTALL {name}")
            self.connection.execute(f"LOAD {name}")
        except duckdb.Error as error:
            raise RuntimeError(
                f"the DuckDB extension {name} could not be installed: INSTALL downloads it once from extensions.duckdb.org; "
                f"install duckdb-core-ext-{name} with pip or set VECDSL_DUCKDB_EXTENSIONS to a directory that holds it ({error})"
            ) from error

    def close(self) -> None:
        self.connection.close()


def connect(path: str, read_only: bool = False, extension_directory: str | None = None) -> Client:
    return Client(path, read_only, extension_directory)


def _plain(value: Any) -> Any:
    """Integral floats as integers, so that JSON text reads 35, not 35.0, in every host language."""
    if isinstance(value, float) and value.is_integer() and math.isfinite(value) and abs(value) < 1e15:
        return int(value)
    if isinstance(value, (list, tuple)):
        return [_plain(item) for item in value]
    if isinstance(value, dict):
        return {str(key): _plain(item) for key, item in value.items()}
    return value


def _text(value: Any) -> str | None:
    """A parameter as text: strings as they are, booleans and numbers in JSON form, lists and objects as JSON."""
    if value is None or isinstance(value, str):
        return value
    return json.dumps(_plain(value), separators=(",", ":"), ensure_ascii=False)


def _value(value: Any) -> Any:
    """Result values in one form for every host language: floats rounded, integral floats as integers."""
    if isinstance(value, float):
        rounded = round(value, _DIGITS)
        return int(rounded) if rounded.is_integer() else rounded
    if isinstance(value, list):
        return [_value(item) for item in value]
    if isinstance(value, dict):
        return {key: _value(item) for key, item in value.items()}
    return value


def _decode(value: Any) -> Any:
    return _value(json.loads(value) if isinstance(value, str) else value)


def _run(client: Client, step: dict[str, Any]) -> Any:
    """One step: the decoded rows of a query, or {counter: changed rows} of a write."""
    params = [_text(value) for value in step.get("params", ())]
    cursor = client.connection.execute(step["sql"], params) if params else client.connection.execute(step["sql"])
    rows = cursor.fetchall() if cursor.description else []
    counter = step.get("counter")
    if counter is None:
        return [_decode(row[0]) for row in rows]
    changed = int(rows[0][0]) if rows else 0
    result = {counter: changed}
    if step.get("skipped"):
        result["skipped"] = len(step["params"][0]) - changed
    return result


def _settings(client: Client, settings: dict[str, str] | None) -> list[str]:
    applied = []
    for name, setting in (settings or {}).items():
        if not _SETTING.fullmatch(name) or not _SETTING_VALUE.fullmatch(setting):
            raise ValueError(f"invalid DuckDB setting {name} = {setting}")
        client.connection.execute(f"SET {name} = {setting}")
        applied.append(name)
    return applied


def _transaction(client: Client, steps: Sequence[dict[str, Any]], settings: dict[str, str] | None = None) -> list[Any]:
    """The steps in one transaction, then each distinct refresh statement once: rebuilding an fts index twice in one
    transaction fails at commit (DuckDB 2.0.0, measured)."""
    applied = _settings(client, settings)
    try:
        client.connection.execute("BEGIN TRANSACTION")
        try:
            results = [_run(client, step) for step in steps]
            for sql in dict.fromkeys(sql for step in steps for sql in step.get("refresh") or ()):
                client.connection.execute(sql)
        except BaseException:
            client.connection.execute("ROLLBACK")
            raise
        client.connection.execute("COMMIT")
        return results
    finally:
        for name in applied:
            client.connection.execute(f"RESET {name}")


def query(client: Client, sql: str, params: Sequence[Any] = (), settings: dict[str, str] | None = None) -> list[Any]:
    """The JSON values of a query's rows."""
    return _transaction(client, [{"sql": sql, "params": params}], settings)[0]


def value(client: Client, sql: str, params: Sequence[Any] = (), settings: dict[str, str] | None = None) -> Any:
    """The JSON value of the first row, or None."""
    rows = query(client, sql, params, settings)
    return rows[0] if rows else None


def exists(client: Client, sql: str, params: Sequence[Any] = ()) -> bool:
    return bool(value(client, sql, params))


def change(client: Client, sql: str, counter: str, params: Sequence[Any] = (), refresh: Sequence[str] = (),
           skipped: bool = False) -> dict[str, int]:
    """A write and the statements that refresh what depends on it (full-text indexes), in one transaction: {counter: rows}."""
    step: dict[str, Any] = {"sql": sql, "params": params, "counter": counter, "refresh": refresh, "skipped": skipped}
    return _transaction(client, [step])[0]


def execute(client: Client, steps: Sequence[dict[str, Any]]) -> None:
    """Statements without results (DDL) in one transaction."""
    _transaction(client, steps)


def transaction(client: Client, steps: Sequence[dict[str, Any]]) -> list[Any]:
    """The statements of a vecDSL transaction in one DuckDB transaction; any failure rolls back all of them."""
    return [result[0] if isinstance(result, list) and result else (None if isinstance(result, list) else result)
            for result in _transaction(client, steps)]


def read_records(client: Client, location: str) -> list[dict[str, Any]]:
    """Records of a local JSON array or JSON Lines file (file:// URI or path)."""
    path = location[len("file://"):] if location.startswith("file://") else location
    with open(path, encoding="utf-8") as handle:
        text = handle.read()
    stripped = text.lstrip()
    if stripped.startswith("["):
        return json.loads(stripped)
    return [json.loads(line) for line in text.splitlines() if line.strip()]


def import_file(client: Client, sql: str, location: str, counter: str, params: Sequence[Any] = (), batch_size: int = _BATCH,
                refresh: Sequence[str] = (), skipped: bool = False) -> dict[str, int]:
    """A local file written in batches by one INSERT statement ($1 is the batch), all in one transaction."""
    records = read_records(client, location)
    starts = list(range(0, len(records), batch_size))
    steps = [{"sql": sql, "params": [records[start:start + batch_size], *params], "counter": counter, "skipped": skipped,
              "refresh": refresh if start + batch_size >= len(records) else ()} for start in starts]
    totals: dict[str, int] = {counter: 0}
    for counts in _transaction(client, steps):
        for key, count in counts.items():
            totals[key] = totals.get(key, 0) + count
    return totals
